#include <charconv>
#include <map>
#include <optional>
#include <string>
#include <string_view>
#include <utility>
#include <vector>

// ---- tinyini: a small library. Read its comments; do not change it. ----
namespace tinyini
{
    /// A parsed INI-style configuration.
    ///
    /// Format, one item per line:
    ///   [section]          starts a section; spaces around the name are ignored
    ///   key = value        spaces around the key and the value are ignored
    ///   ; comment, # comment, and blank lines are skipped
    /// Keys that appear before any [section] belong to the section "" (empty name).
    /// Section and key names are case-sensitive. A key repeated in a section
    /// replaces the earlier value.
    class Config
    {
    public:
        /// Parses `text`. On a malformed line (a '[' without a closing ']', an empty
        /// section name, a line without '=', or an empty key) returns std::nullopt
        /// and, if `errorLine` is not null, stores that line's number (1-based).
        static std::optional<Config> parse(std::string_view text, int* errorLine = nullptr)
        {
            Config config;
            std::string current;
            int lineNumber{ 0 };
            std::size_t at{ 0 };
            while (at <= text.size())
            {
                std::size_t end{ text.find('\n', at) };
                if (end == std::string_view::npos) end = text.size();
                std::string_view line{ trim(text.substr(at, end - at)) };
                at = end + 1;
                ++lineNumber;
                if (line.empty() || line[0] == ';' || line[0] == '#') continue;
                if (line[0] == '[')
                {
                    const std::string_view name{ line.back() == ']' ? trim(line.substr(1, line.size() - 2)) : std::string_view{} };
                    if (line.back() != ']' || line.size() < 2 || name.empty()) return fail(errorLine, lineNumber);
                    current = std::string(name);
                    config.section(current);
                    continue;
                }
                const std::size_t eq{ line.find('=') };
                if (eq == std::string_view::npos) return fail(errorLine, lineNumber);
                const std::string_view key{ trim(line.substr(0, eq)) };
                if (key.empty()) return fail(errorLine, lineNumber);
                config.section(current)[std::string(key)] = std::string(trim(line.substr(eq + 1)));
            }
            return config;
        }

        /// @return a pointer to the value, or nullptr if the section or the key does
        ///         not exist. The pointer stays valid until this Config is destroyed.
        const std::string* find(std::string_view section, std::string_view key) const
        {
            for (const auto& [name, keys] : sections_)
            {
                if (name != section) continue;
                const auto it{ keys.find(std::string(key)) };
                return it == keys.end() ? nullptr : &it->second;
            }
            return nullptr;
        }

        /// @return the value as a whole number, read with std::from_chars in base 10
        ///         (so a leading '+' or any extra character is not accepted).
        ///         std::nullopt if the value is missing OR is not such a number.
        std::optional<long long> findInt(std::string_view section, std::string_view key) const
        {
            const std::string* text{ find(section, key) };
            if (!text || text->empty()) return std::nullopt;
            long long value{ 0 };
            const auto [ptr, ec] { std::from_chars(text->data(), text->data() + text->size(), value) };
            if (ec != std::errc{} || ptr != text->data() + text->size()) return std::nullopt;
            return value;
        }

        /// @return true for "true", "yes" or "1"; false for "false", "no" or "0"
        ///         (exactly these, in lower case). std::nullopt if the value is
        ///         missing OR is anything else.
        std::optional<bool> findBool(std::string_view section, std::string_view key) const
        {
            const std::string* text{ find(section, key) };
            if (!text) return std::nullopt;
            if (*text == "true" || *text == "yes" || *text == "1") return true;
            if (*text == "false" || *text == "no" || *text == "0") return false;
            return std::nullopt;
        }

    private:
        static std::string_view trim(std::string_view s)
        {
            while (!s.empty() && (s.front() == ' ' || s.front() == '\t' || s.front() == '\r')) s.remove_prefix(1);
            while (!s.empty() && (s.back() == ' ' || s.back() == '\t' || s.back() == '\r')) s.remove_suffix(1);
            return s;
        }

        static std::optional<Config> fail(int* errorLine, int line)
        {
            if (errorLine) *errorLine = line;
            return std::nullopt;
        }

        std::map<std::string, std::string>& section(const std::string& name)
        {
            for (auto& [existing, keys] : sections_) if (existing == name) return keys;
            sections_.emplace_back(name, std::map<std::string, std::string>{});
            return sections_.back().second;
        }

        std::vector<std::pair<std::string, std::map<std::string, std::string>>> sections_;
    };
}
// ---- end of tinyini ----

