struct ServerSettings { std::string host; int port; bool tls; int workers; };

std::optional<ServerSettings> loadSettings(std::string_view text, std::string& error)
{
    int line{ 0 };
    const auto config{ tinyini::Config::parse(text, &line) };
    if (!config)
    {
        error = "line " + std::to_string(line);
        return std::nullopt;
    }
    ServerSettings s{ "localhost", 0, false, 4 };

    if (const std::string* host{ config->find("server", "host") })
    {
        if (host->empty()) { error = "bad server.host"; return std::nullopt; }
        s.host = *host;
    }

    if (!config->find("server", "port")) { error = "missing server.port"; return std::nullopt; }
    const auto port{ config->findInt("server", "port") };
    if (!port || *port < 1 || *port > 65535) { error = "bad server.port"; return std::nullopt; }
    s.port = static_cast<int>(*port);

    if (config->find("server", "tls"))
    {
        const auto tls{ config->findBool("server", "tls") };
        if (!tls) { error = "bad server.tls"; return std::nullopt; }
        s.tls = *tls;
    }

    if (config->find("pool", "size"))
    {
        const auto size{ config->findInt("pool", "size") };
        if (!size || *size < 1 || *size > 256) { error = "bad pool.size"; return std::nullopt; }
        s.workers = static_cast<int>(*size);
    }

    error.clear();
    return s;
}

unitTests:
std::string problem(std::string_view text) {
    std::string error{ "untouched" };
    const auto s{ loadSettings(text, error) };
    return s ? "ok" : error;
}
TEST("a full configuration") {
    std::string error{ "x" };
    const auto s{ loadSettings("; my server
[server]
host = example.org
port = 8443
tls = yes

[pool]
size = 16
", error) };
    CHECK(s.has_value());
    if (s) CHECK(s->host == "example.org" && s->port == 8443 && s->tls && s->workers == 16);
    CHECK_EQ(error, std::string(""));
}
TEST("defaults") {
    std::string error;
    const auto s{ loadSettings("[server]
port=80", error) };
    CHECK(s.has_value());
    if (s) CHECK(s->host == "localhost" && s->port == 80 && !s->tls && s->workers == 4);
}
TEST("missing is not the same as bad") {
    CHECK_EQ(problem("[server]
host = a
"), std::string("missing server.port"));
    CHECK_EQ(problem("port = 80
"), std::string("missing server.port"));
    CHECK_EQ(problem("[Server]
port = 80
"), std::string("missing server.port"));
    CHECK_EQ(problem("[server]
port =
"), std::string("bad server.port"));
    CHECK_EQ(problem("[server]
port = eighty
"), std::string("bad server.port"));
    CHECK_EQ(problem("[server]
port = +80
"), std::string("bad server.port"));
    CHECK_EQ(problem("[server]
port = 0
"), std::string("bad server.port"));
    CHECK_EQ(problem("[server]
port = 65536
"), std::string("bad server.port"));
    CHECK_EQ(problem("[server]
port = 65535
"), std::string("ok"));
}
TEST("other bad values") {
    CHECK_EQ(problem("[server]
host =
port = 80
"), std::string("bad server.host"));
    CHECK_EQ(problem("[server]
port = 80
tls = True
"), std::string("bad server.tls"));
    CHECK_EQ(problem("[server]
port = 80
tls = 0
"), std::string("ok"));
    CHECK_EQ(problem("[server]
port = 80
[pool]
size = 0
"), std::string("bad pool.size"));
    CHECK_EQ(problem("[server]
port = 80
[pool]
size = 257
"), std::string("bad pool.size"));
    CHECK_EQ(problem("[server]
port = 80
[pool]
threads = 999
"), std::string("ok"));
}
TEST("checked in order") {
    CHECK_EQ(problem("[server]
host =
"), std::string("bad server.host"));
    CHECK_EQ(problem("[server]
port = x
tls = maybe
"), std::string("bad server.port"));
}
TEST("parse errors give the line") {
    CHECK_EQ(problem("[server]
port = 80
junk
"), std::string("line 3"));
    CHECK_EQ(problem("

[server
"), std::string("line 3"));
    CHECK_EQ(problem("[]
"), std::string("line 1"));
    CHECK_EQ(problem("[server]
port = 80
= 5
"), std::string("line 3"));
}
TEST("repeated keys and windows line endings") {
    std::string error;
    const auto s{ loadSettings("[server]
port = 1
port = 2
", error) };
    CHECK(s.has_value() && s->port == 2);
}

